#!/usr/bin/env node
// One gate for the shipped music. The cues and the music index (music.json:
// catalog, routing and every cue manifest) under public/audio are generated by
// tear-music (`node tools/music.mjs publish`); this checks that what was published
// is complete and self-consistent:
//   - the index, its catalog and its routing have their expected formats, and the
//     index carries exactly the cue.json files on disk;
//   - the default work, every routed work and every playable catalog work has a cue;
//   - every file a cue.json names exists, and nothing else is in public/audio/cues;
//   - every other build target's encode (opus-<target>/) mirrors opus/ file for file;
//   - each cue stays inside its size budget for every target;
//   - no shipped audio file carries a source-tool tag.
import { closeSync, existsSync, openSync, readFileSync, readSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const audio = path.join(root, "public", "audio");
const cuesDir = path.join(audio, "cues");
/** Matches tear-music's LIMITS.cueBytes. */
const CUE_BYTES = 2_600_000;
const errors = [];
const fail = (message) => errors.push(message);

function readJson(file) {
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch (error) {
    fail(`${path.relative(root, file)}: ${error.message}`);
    return null;
  }
}

function filesUnder(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? filesUnder(full) : [full];
  });
}

const index = readJson(path.join(audio, "music.json"));
if (index && index.format !== "tear-music-index") fail("music.json: format is not tear-music-index");
const catalog = index?.catalog ?? null;
const routing = index?.routing ?? null;
if (catalog?.format !== "tear-music-catalog") fail("music.json: catalog format is not tear-music-catalog");
if (routing?.format !== "tear-music-routing") fail("music.json: routing format is not tear-music-routing");

const required = new Map();
const need = (id, why) => required.set(id, [...(required.get(id) ?? []), why]);
if (routing) {
  need(routing.defaultWorkId, "routing default");
  for (const rule of routing.rules ?? []) {
    const ids =
      rule.selection?.type === "primary"
        ? [rule.selection.workId]
        : (rule.selection?.entries ?? []).map((entry) => entry.workId);
    for (const id of ids) need(id, `route ${rule.id}`);
  }
}
const stationIds = new Set((catalog?.stations ?? []).map((station) => station.id));
for (const work of catalog?.works ?? []) {
  for (const station of work.stations ?? []) {
    if (!stationIds.has(station)) fail(`catalog ${work.id}: unknown station ${station}`);
  }
  const game = work.versions?.["adaptive-game"];
  if (game?.available) {
    need(work.id, "catalog");
    if (game.cue !== `audio/cues/${work.id}`)
      fail(`catalog ${work.id}: cue path ${game.cue} is not audio/cues/${work.id}`);
  }
}

const referenced = new Set();
const sizes = new Map([["web", []]]);
/** Build targets with their own encode, from the opus-<target>/ folders present. */
const targets = new Set(
  existsSync(cuesDir)
    ? readdirSync(cuesDir).flatMap((cue) =>
        existsSync(path.join(cuesDir, cue)) && statSync(path.join(cuesDir, cue)).isDirectory()
          ? readdirSync(path.join(cuesDir, cue))
              .filter((name) => name.startsWith("opus-"))
              .map((name) => name.slice(5))
          : [],
      )
    : [],
);
for (const target of targets) sizes.set(target, []);
for (const [id, why] of required) {
  const dir = path.join(cuesDir, id);
  const cueFile = path.join(dir, "cue.json");
  if (!existsSync(cueFile)) {
    fail(`${id}: no cue.json (needed by ${why.join(", ")})`);
    continue;
  }
  const cue = readJson(cueFile);
  if (!cue) continue;
  referenced.add(cueFile);
  if (cue.format !== "tear-score-stem-cue") fail(`${id}: cue format is ${cue.format}`);
  if (JSON.stringify(index?.cues?.[id]) !== JSON.stringify(cue)) fail(`${id}: music.json does not carry this cue.json`);
  if (cue.id !== id) fail(`${id}: cue.json id is ${cue.id}`);
  const urls = [
    ...(cue.stems ?? []).flatMap((stem) => (stem.sources ?? []).map((source) => source.url)),
    ...(cue.bossIntro?.asset ? [cue.bossIntro.asset] : []),
  ];
  if (!cue.stems?.length) fail(`${id}: cue has no stems`);
  let bytes = statSync(cueFile).size;
  for (const url of urls) {
    const file = path.join(dir, url);
    if (!existsSync(file)) {
      fail(`${id}: missing ${url}`);
      continue;
    }
    referenced.add(file);
    bytes += statSync(file).size;
  }
  for (const [tier, gains] of Object.entries(cue.tiers ?? {})) {
    for (const stemId of Object.keys(gains)) {
      if (!cue.stems.some((stem) => stem.id === stemId)) fail(`${id}: tier ${tier} names unknown stem ${stemId}`);
    }
  }
  if (bytes > CUE_BYTES) fail(`${id}: ${bytes} B is over the ${CUE_BYTES} B cue budget`);
  sizes.get("web").push([id, bytes]);
  for (const target of targets) {
    const mirror = path.join(dir, `opus-${target}`);
    const names = urls.map((url) => path.basename(url)).sort();
    const present = existsSync(mirror) ? readdirSync(mirror).sort() : [];
    if (JSON.stringify(present) !== JSON.stringify(names))
      fail(`${id}: opus-${target}/ has [${present.join(", ")}], expected [${names.join(", ")}]`);
    let targetBytes = statSync(cueFile).size;
    for (const name of names.filter((n) => present.includes(n))) {
      referenced.add(path.join(mirror, name));
      targetBytes += statSync(path.join(mirror, name)).size;
    }
    if (targetBytes > CUE_BYTES) fail(`${id}: ${target} ${targetBytes} B is over the ${CUE_BYTES} B cue budget`);
    sizes.get(target).push([id, targetBytes]);
  }
}

for (const id of Object.keys(index?.cues ?? {}))
  if (!required.has(id)) fail(`music.json carries ${id}, which nothing plays`);
if (existsSync(cuesDir)) {
  for (const file of filesUnder(cuesDir)) {
    if (!referenced.has(file)) fail(`unreferenced: ${path.relative(root, file).replaceAll("\\", "/")}`);
  }
}

/** Matches tear-music's SOURCE_LABEL; tags live in the first 64 KiB of an Ogg file. */
const SOURCE_LABEL = /suno|made with|ai[- ]generated|udio\.com/iu;
for (const file of filesUnder(audio)) {
  const fd = openSync(file, "r");
  const head = Buffer.alloc(65536);
  const n = readSync(fd, head, 0, head.length, 0);
  closeSync(fd);
  if (SOURCE_LABEL.test(head.subarray(0, n).toString("latin1")))
    fail(`source-tool tag in ${path.relative(root, file).replaceAll("\\", "/")}`);
  // Shipped music files are public: they name people by handle, never by contact address.
  if (file.endsWith(".json") && /[\w.+-]+@[\w-]+\.[a-z]{2,}/iu.test(readFileSync(file, "utf8")))
    fail(`contact address in ${path.relative(root, file).replaceAll("\\", "/")}`);
}

if (errors.length) {
  for (const message of errors) console.error(`check:music: ${message}`);
  process.exit(1);
}
const totals = [...sizes].map(
  ([target, list]) => `${target} ${(list.reduce((sum, [, bytes]) => sum + bytes, 0) / 1048576).toFixed(2)} MiB`,
);
console.log(`check:music: ${sizes.get("web").length} cues complete (${totals.join(", ")}), nothing unreferenced`);
